*/

with feeders as (
    select
        md5(upper('HUB_DISTRIBUTION_CHANNEL|' || (HUB_DISTRIBUTION_CHANNEL_BK__chatbot_id))) as HUB_DISTRIBUTION_CHANNEL_HK
        , service_name as BOT_SERVICE_NAME
        , service_hit_cnt as SERVICE_INVOCATION_COUNT
        , request_type as REQUEST_TYPE
        , date_generated as UTILISATION_RECORD_DATE
        , reference_no as SESSION_BUSINESS_REFERENCE
        , prev_reference_no as PREVIOUS_SESSION_BUSINESS_REFERENCE
        , 'BJAZ_BOT_UTILIZATION_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bot_utilization_dtls') }}
    where (nullif('CHATBOT:' || nullif(trim(chatbot_id),''), 'CHATBOT:')) is not null
),

resolved as (
    select
        HUB_DISTRIBUTION_CHANNEL_HK,
        max(case when SOURCE_RUN = 'opus_health_delta3' then BOT_SERVICE_NAME end) as BOT_SERVICE_NAME,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SERVICE_INVOCATION_COUNT end) as SERVICE_INVOCATION_COUNT,
        max(case when SOURCE_RUN = 'opus_health_delta3' then REQUEST_TYPE end) as REQUEST_TYPE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then UTILISATION_RECORD_DATE end) as UTILISATION_RECORD_DATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SESSION_BUSINESS_REFERENCE end) as SESSION_BUSINESS_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then PREVIOUS_SESSION_BUSINESS_REFERENCE end) as PREVIOUS_SESSION_BUSINESS_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_DISTRIBUTION_CHANNEL_HK
),

hashed as (
    select
        *,
        case when BOT_SERVICE_NAME is not null or SERVICE_INVOCATION_COUNT is not null or REQUEST_TYPE is not null or UTILISATION_RECORD_DATE is not null or SESSION_BUSINESS_REFERENCE is not null or PREVIOUS_SESSION_BUSINESS_REFERENCE is not null
                     then md5(upper(coalesce(cast(BOT_SERVICE_NAME as varchar), '') || '|' || coalesce(cast(SERVICE_INVOCATION_COUNT as varchar), '') || '|' || coalesce(cast(REQUEST_TYPE as varchar), '') || '|' || coalesce(cast(UTILISATION_RECORD_DATE as varchar), '') || '|' || coalesce(cast(SESSION_BUSINESS_REFERENCE as varchar), '') || '|' || coalesce(cast(PREVIOUS_SESSION_BUSINESS_REFERENCE as varchar), '')))
                end as SAT_CHANNEL_BOT_SERVICE_UTILISATION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_DISTRIBUTION_CHANNEL_HK is not null
  and SAT_CHANNEL_BOT_SERVICE_UTILISATION_HASHDIFF is not null
